INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l09',2,2,9,'A cold welcome','冷遇','时间介词 at/in/on(at钟点/时刻词 · in月年季节/上午下午晚上/一段时间后=将来 · on星期日期具体某天 · 易混对比)','除夕夜去市政厅看大钟报时 · 大钟却在差5分12点时停摆,''拒绝''迎接新年','{"q":"Listen and answer — When did they go to the Town Hall?","options":["On New Year''s Eve","On New Year''s Day","In the summer","On a Monday morning"],"answer_index":0}'::jsonb,'{"title":"at / in / on:时间介词怎么选","intro":"本课讲怎么在时间前面用对 at、in、on。全用本课句子举例。","table":{"headers":["规则","本课 / 常见例子"],"rows":[["at + 具体钟点 / 某个时刻词:at 8 o''clock / at night / at noon / at that moment","The clock stopped at five to twelve."],["in + 月 / 年 / 季节 / 上午下午晚上:in July / in 2020 / in summer / in the morning","It happened in December, in the evening."],["on + 星期 / 日期 / 具体某一天:on Monday / on April 27th / on my birthday","We went to the Town Hall on Saturday night."],["in + 一段时间 = ''…之后''(将来):in ten minutes = 十分钟后","The clock would strike twelve in a few minutes."]]},"specialRules":[{"rule":"小心对比:in the morning(上午)但 on Monday morning(具体某天上午);at night 但 in the evening","mark":"易混对比"},{"rule":"只说月份用 in(in October);说到具体某天用 on(on October 5th)","mark":"月 vs 日"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l09',1,NULL,'It was New Year''s Eve, and that year it fell on the weekend.','那是除夕夜,那年除夕正好赶在周末。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l09',2,NULL,'On Saturday night, my friends and I went to the old Town Hall.','周六晚上,我和朋友们去了那座老市政厅。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l09',3,NULL,'A huge crowd gathered on the sidewalk under the big clock.','一大群人聚集在大钟下面的人行道上。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l09',4,NULL,'People stood in a long line, waiting to welcome the New Year.','人们排成长长的一队,等着迎接新年。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l09',5,NULL,'The clock would strike twelve at midnight, in just a few minutes.','再过几分钟,大钟就会在午夜敲响十二点。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l09',6,NULL,'But at five to twelve, the big clock suddenly stopped!','可就在差五分十二点时,那座大钟突然停了!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l09',7,NULL,'The minute hand did not move at all.','分针一动也不动。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l09',8,NULL,'We waited and waited in the cold, but nothing happened.','我们在寒风里等了又等,却什么也没发生。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l09',9,NULL,'At that moment, someone shouted, "It''s already past twelve — the clock has stopped!"','就在那一刻,有人喊道:"已经过十二点了——钟停了!"') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l09',10,NULL,'I looked at my watch, and it was true: the clock refused to welcome the New Year.','我看了看手表,果真如此:大钟拒绝迎接新年。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l09',11,NULL,'Everybody began to laugh, and then we all started to sing.','大家都笑了起来,接着我们一起唱起歌来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
